contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount) + (amount)); require(amount <= 1000000000000000000000000000000);
        require(address(this).balance >= amount);

        // Fund c via multiplicate with c as recipient (fresh c has balance 0,
        // so amount >= balance holds and the call succeeds, c ends with amount).
        c.multiplicate{value: amount}(payable(address(c))); if (__ESBMC_reverted()) return;

        // Then use Command to send value back to this test contract (empty data,
        // this contract has a receive, so the forwarded call succeeds).
        c.Command{value: amount}(payable(address(this)), ""); if (__ESBMC_reverted()) return;

        // Owner must be immutable through the public surface.
        assert(c.Owner() == address(this));
    }

    receive() external payable {}
}

